head.script:
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)

scwin.fn_GetPar, scwin.fn_SetPar, scwin.strCdSch;
scwin.fr_SecuGrpId; // 증권그룹ID
scwin.fr_IsurCd;
scwin.fr_SearchType; // 예비심사종목을 조회할지, 신규상장종목을 조회할지의 구분값
scwin.fr_mktTpCd; // 유가종목, 코스닥종목, 유가+코스닥전체종목 조회구분값

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        window.document.body.scroll = "no";
        let arrPar = new Array();
        /***************************************
        opener에  fn_GetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 업종조회후  최초 지정 코드값이 없는 상태
        opener에  fn_SetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 선택한 코드값과 코드명칭을 지정하지 않는다.
         ***************************************/
        const parentWin = $c.frame.path("../");
        const obj = parentWin.txb_ISUR_CD;
        if (obj !== undefined) {
            scwin.fr_IsurCd = obj.getValue();
        } else {
            tr_Isur_Cd = "";
        }
        fn_GetParForIsuCd = parentWin.fn_GetParForIsuCd;
        fn_SetParForIsuCd = parentWin.fn_SetParForIsuCd;
        // alert('[fr_SearchTyp]'+fr_SearchTyp);

        if (fn_GetParForIsuCd !== undefined) {
            fn_GetParForIsuCd(arrPar);
            strSch = (arrPar.length >= 1 ? arrPar[0] : "");
            scwin.fr_SecuGrpId = (arrPar.length >= 3 ? arrPar[2] : "");
            scwin.fr_mktTpCd = (arrPar.length >= 4 ? arrPar[3] : "");
            scwin.fr_SearchType = (arrPar.length >= 5 ? arrPar[4] : "");
        }
        txb_Search.focus();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05107.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name txb_Search_onkeydown
 * @description txb_Search 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_Search_onkeydown = async function() {
    try {
        if (event.keyCode === 13) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05107.txb_Search_onkeydown" });
    }
};

/**
 * @method
 * @name dts_OnLoadError
 * @description dts 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_OnLoadError = async function() {
    try {
        await $c.win.alert(dts);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05107.dts_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_OnLoadCompleted
 * @description dts 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts.errorMsg) {
            await $c.win.alert(dts.errorMsg);
        } else {
            txb_TotCnt.setValue("총 " + rowcount + " 건");

            // 초기1회 초기값으로 설정된 회사코드를 검색한다.
            if (scwin.strCdSch !== "") {
                for (let i = 1; i <= dts.getRowCount(); i++) {
                    if (scwin.strCdSch === dts.getCellData(i, 1)) {
                        dts.setRowPosition(i, 0);
                        break;
                    }
                }
                scwin.strCdSch = "";
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05107.dts_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_IsuInst_OnDblClick
 * @description grd_IsuInst 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_IsuInst_OnDblClick = async function(row, colid) {
    try {
        let arrPar = new Array();
        if (fn_SetParForIsuCd !== undefined) {
            arrPar[0] = {
                ISU_CD: dts.getCellData(dts.getRowPosition(), "ISU_CD"),
                ISU_NM: dts.getCellData(dts.getRowPosition(), "ISU_NM"),
                ISU_ENG_NM: dts.getCellData(dts.getRowPosition(), "ISU_ENG_NM"),
                ISUR_CD: dts.getCellData(dts.getRowPosition(), "ISUR_CD"),
                BZ_PROCS_NO: dts.getCellData(dts.getRowPosition(), "BZ_PROCS_NO"), // 신규상장에서 사용할값.
                DBCLICKYN: "Y"
            };
            fn_SetParForIsuCd(arrPar);
        }
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05107.grd_IsuInst_OnDblClick" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05107.img_Search_onclick" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05107.img_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    // alert('[fr_SearchTyp]'+fr_SearchTyp);
    url += "&ISUR_CD=" + scwin.fr_IsurCd;
    url += "&ISU_NM=" + txb_Search.getValue();
    url += "&SECUGRP_ID=" + scwin.fr_SecuGrpId;
    url += "&SEARCH_TYPE=" + scwin.fr_SearchType;
    url += "&SPOT_ISU_TRD_MKT_TP_CD=" + scwin.fr_mktTpCd;
    const sbmOptions = {
        id : "sbm_dts",
        action : "/KindStk.do",
        ref : "",
        target : "dts=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
